package com.opensocket.aievent.core.iam.token.domain;import static org.junit.jupiter.api.Assertions.*;import com.opensocket.aievent.core.iam.security.contract.*;import java.time.*;import org.junit.jupiter.api.Test;class AccessTokenTest{@Test void oneTimeTokenCannotReplay(){Instant now=Instant.parse("2026-07-23T00:00:00Z");AccessToken t=AccessToken.issue("t",new TokenId("id"),AccessTokenType.PASSWORD_RESET_TOKEN,new PrincipalRef(PrincipalRef.PrincipalType.USER,"u"),"reset","odp_reset_x","1234",new TokenHash("HMAC","x"),TokenScope.oneTime("reset"),now,now.plusSeconds(60),SecurityEpoch.ZERO,"");AccessToken c=t.consume(now.plusSeconds(1));assertEquals(AccessTokenStatus.CONSUMED,c.status());assertThrows(TokenDomainException.class,()->c.consume(now.plusSeconds(2)));}}
